<?php
declare(strict_types=1);

namespace P2K\Shared;

/**
 * Explicit Chess.com username-search audit for Admin > Traffic / Visitors.
 *
 * Unlike MatchAssistantUsage (completed analyses), this records every valid
 * submitted search, including zero-result and failed analyses. No IP, cookie,
 * persistent user identifier or caller-supplied timestamp is stored.
 * Timestamps are generated by the server in UTC.
 */
final class NameSearchUsage
{
    private const SOURCES=['match-assistant','recruitment-radar'];
    private const MAX_REPORT=3000;

    public static function validUsername(string $username):?string
    {
        $username=trim($username);
        return preg_match('/^[A-Za-z0-9_-]{2,25}$/D',$username)===1?strtolower($username):null;
    }

    public static function record(string $root,string $username,string $source):array
    {
        $name=self::validUsername($username);
        if($name===null)throw new \InvalidArgumentException('A valid Chess.com username is required.');
        if(!in_array($source,self::SOURCES,true))throw new \InvalidArgumentException('Unknown search source.');
        $now=time();$stamp=gmdate('Y-m-d\TH:i:s\Z',$now);
        $day=gmdate('Y-m-d',$now);
        $dir=rtrim($root,'/\\').'/logs/name-search';
        if(!is_dir($dir)&&!@mkdir($dir,0700,true)&&!is_dir($dir))throw new \RuntimeException('Name search log directory is unavailable.');
        $path=$dir.'/'.$day.'.jsonl';
        $entry=['schemaVersion'=>1,'timestamp'=>$stamp,'username'=>$name,'source'=>$source];
        $json=json_encode($entry,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n";
        $handle=@fopen($path,'ab');
        if(!$handle)throw new \RuntimeException('Unable to open search audit log.');
        try{
            if(!flock($handle,LOCK_EX))throw new \RuntimeException('Unable to lock search audit log.');
            $count=fwrite($handle,$json);
            if($count===false||$count!==strlen($json))throw new \RuntimeException('Unable to write complete search audit log entry.');
            fflush($handle);
        }finally{flock($handle,LOCK_UN);fclose($handle);}
        @chmod($path,0600);
        return $entry;
    }

    public static function report(string $root,int $days=90,int $limit=self::MAX_REPORT):array
    {
        $days=max(1,min(366,$days));$limit=max(1,min(5000,$limit));
        $utc=new \DateTimeZone('UTC');
        $to=new \DateTimeImmutable('today',$utc);
        $from=$to->modify('-'.($days-1).' days');
        $counts=['match-assistant'=>0,'recruitment-radar'=>0];
        $daily=[];$byUser=[];$entries=[];$invalid=0;
        $dir=rtrim($root,'/\\').'/logs/name-search';
        for($date=$from;$date<=$to;$date=$date->modify('+1 day')){
            $day=$date->format('Y-m-d');
            $stats=['date'=>$day,'match_assistant'=>0,'recruitment_radar'=>0,'total'=>0,'usernames'=>[]];
            $path=$dir.'/'.$day.'.jsonl';
            if(is_file($path)){
                $file=@fopen($path,'rb');
                if(!$file){$invalid++;}
                else{
                    while(($line=fgets($file))!==false){
                        $row=json_decode($line,true);
                        if(!is_array($row)){$invalid++;continue;}
                        $name=self::validUsername((string)($row['username']??''));
                        $source=(string)($row['source']??'');
                        $stamp=(string)($row['timestamp']??'');
                        if($name===null||!in_array($source,self::SOURCES,true)||
                            !preg_match('/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$/D',$stamp)||
                            substr($stamp,0,10)!==$day){$invalid++;continue;}
                        $counts[$source]++;
                        $stats[$source==='match-assistant'?'match_assistant':'recruitment_radar']++;
                        $stats['total']++;$stats['usernames'][$name]=true;
                        $entries[]=['timestamp'=>$stamp,'username'=>$name,'source'=>$source];
                        if(!isset($byUser[$name]))$byUser[$name]=[
                            'username'=>$name,'total'=>0,'match_assistant'=>0,
                            'recruitment_radar'=>0,'lastSearchAt'=>''
                        ];
                        $byUser[$name]['total']++;
                        $byUser[$name][$source==='match-assistant'?'match_assistant':'recruitment_radar']++;
                        if(strcmp($stamp,$byUser[$name]['lastSearchAt'])>0)$byUser[$name]['lastSearchAt']=$stamp;
                    }
                    fclose($file);
                }
            }
            $stats['distinctUsernames']=count($stats['usernames']);unset($stats['usernames']);
            $daily[]=$stats;
        }
        usort($entries,static fn(array $a,array $b):int=>strcmp($b['timestamp'],$a['timestamp']));
        $users=array_values($byUser);
        usort($users,static fn(array $a,array $b):int=>$b['total']<=>$a['total']?:
            strcmp($b['lastSearchAt'],$a['lastSearchAt'])?:strcmp($a['username'],$b['username']));
        usort($daily,static fn(array $a,array $b):int=>strcmp($b['date'],$a['date']));
        return [
            'range'=>['days'=>$days,'from'=>$from->format('Y-m-d'),'to'=>$to->format('Y-m-d')],
            'summary'=>[
                'total'=>$counts['match-assistant']+$counts['recruitment-radar'],
                'match_assistant'=>$counts['match-assistant'],
                'recruitment_radar'=>$counts['recruitment-radar'],
                'distinct_usernames'=>count($users)
            ],
            'daily'=>$daily,'users'=>$users,'entries'=>array_slice($entries,0,$limit),
            'truncated'=>count($entries)>$limit,'invalidLines'=>$invalid,
            'note'=>'Every valid explicitly submitted username search; timestamps in UTC. Does not imply that a recommendation analysis completed successfully.'
        ];
    }
}
